package com.aistock.market.alert;
import com.aistock.common.BusinessException;
import com.aistock.market.forecast.ForecastCandidate;
import com.aistock.market.quotation.*;
import java.math.BigDecimal;import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AlertEvidenceValidatorTest {
 static final Instant NOW=Instant.parse("2026-10-10T06:00:00Z");
 static final UUID RAW=UUID.fromString("10000000-0000-0000-0000-000000000001");
 static final String OP="20000000-0000-0000-0000-000000000001";
 static final LocalDate PREV=LocalDate.of(2026,10,8),DAY=LocalDate.of(2026,10,9);
 static RawBar bar(LocalDate date,String close,int status){var p=new BigDecimal(close);return new RawBar(date,p,p,p,p,new BigDecimal("1000"),new BigDecimal("10000"),status,null);}
 static List<TradingDay> days(){return java.util.stream.IntStream.rangeClosed(8,14).mapToObj(d->new TradingDay(LocalDate.of(2026,10,d),d!=10&&d!=11)).toList();}
 static ForecastCandidate source(){return new ForecastCandidate(OP,"SH600030",RAW.toString(),"baostock","baostock-backward-close-over-raw-v1",NOW,"a".repeat(64),List.of(new ForecastCandidate.PairedBar(bar(PREV,"100",1),new BigDecimal("100")),new ForecastCandidate.PairedBar(bar(DAY,"50",1),new BigDecimal("100"))),days().subList(0,2));}
 AlertEvidenceValidator validator(){return new AlertEvidenceValidator(Clock.fixed(NOW,ZoneOffset.UTC));}
 @Test void exRightsPairRetainsComparableValuesRatherThanRawFiftyPercentFall(){var p=validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",1),bar(DAY,"50",1)),days(),source());assertEquals("100",p.previousBackwardClose());assertEquals("100",p.currentBackwardClose());}
 @Test void missingImmediatePreviousBarCannotSkipBackToOlderDate(){assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV.minusDays(1),"100",1),bar(DAY,"50",1)),days(),source()));}
 @Test void suspendedBarCannotProduceComparableChange(){assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",0),bar(DAY,"50",1)),days(),source()));}
 @Test void sourceCannotDisagreeWithFixedRawOrCalendar(){var c=source();var changed=new ArrayList<>(days());changed.set(0,new TradingDay(PREV,false));assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"101",1),bar(DAY,"50",1)),days(),c));assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",1),bar(DAY,"50",1)),changed,c));}
 @Test void sourceIdentityFreshnessAndPositivePricesAreRequired(){var c=source();var variants=List.of(new ForecastCandidate(c.operationId(),"SH600276",c.rawVersionId(),c.provider(),c.definition(),c.fetchedAt(),c.sourcePayloadHash(),c.bars(),c.calendar()),new ForecastCandidate(c.operationId(),c.instrumentId(),c.rawVersionId(),c.provider(),c.definition(),NOW.minusSeconds(301),c.sourcePayloadHash(),c.bars(),c.calendar()),new ForecastCandidate(c.operationId(),c.instrumentId(),c.rawVersionId(),c.provider(),c.definition(),NOW.plusSeconds(6),c.sourcePayloadHash(),c.bars(),c.calendar()),new ForecastCandidate(c.operationId(),c.instrumentId(),c.rawVersionId(),c.provider(),c.definition(),NOW,c.sourcePayloadHash(),List.of(c.bars().get(0),new ForecastCandidate.PairedBar(c.bars().get(1).raw(),BigDecimal.ZERO)),c.calendar()));for(var v:variants)assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",1),bar(DAY,"50",1)),days(),v));}
 @Test void duplicateOrIncompleteSourceDatesAreRejected(){var c=source();for(var bars:List.of(List.of(c.bars().get(0)),List.of(c.bars().get(0),c.bars().get(0)))){var v=new ForecastCandidate(c.operationId(),c.instrumentId(),c.rawVersionId(),c.provider(),c.definition(),NOW,c.sourcePayloadHash(),bars,c.calendar());assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",1),bar(DAY,"50",1)),days(),v));}}

 @Test void longClosureUsesCalendarPreviousSessionRatherThanPreviousNaturalDay(){var previous=LocalDate.of(2026,9,30);var current=LocalDate.of(2026,10,8);var days=new ArrayList<TradingDay>();for(var d=previous;!d.isAfter(current);d=d.plusDays(1))days.add(new TradingDay(d,d.equals(previous)||!d.isBefore(current)&&d.getDayOfWeek().getValue()<6));var raw=List.of(bar(previous,"100",1),bar(current,"101",1));var c=new ForecastCandidate(OP,"SH600030",RAW.toString(),"baostock","baostock-backward-close-over-raw-v1",NOW,"a".repeat(64),List.of(new ForecastCandidate.PairedBar(raw.get(0),new BigDecimal("200")),new ForecastCandidate.PairedBar(raw.get(1),new BigDecimal("202"))),days);var pair=validator().pair(OP,"SH600030",RAW,previous,current,raw,days,c);assertEquals("200",pair.previousBackwardClose());assertEquals("202",pair.currentBackwardClose());}

 @Test void exactBoundaryPrecisionIsPreservedAndExcessScaleRejected(){var c=source();var value=new BigDecimal("1234567890123456.123456789012");var exact=new ForecastCandidate(c.operationId(),c.instrumentId(),c.rawVersionId(),c.provider(),c.definition(),NOW,c.sourcePayloadHash(),List.of(new ForecastCandidate.PairedBar(c.bars().get(0).raw(),value),new ForecastCandidate.PairedBar(c.bars().get(1).raw(),value)),c.calendar());assertEquals("1234567890123456.123456789012",validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",1),bar(DAY,"50",1)),days(),exact).currentBackwardClose());var illegal=new ForecastCandidate(c.operationId(),c.instrumentId(),c.rawVersionId(),c.provider(),c.definition(),NOW,c.sourcePayloadHash(),List.of(c.bars().get(0),new ForecastCandidate.PairedBar(c.bars().get(1).raw(),new BigDecimal("100.0000000000000000001"))),c.calendar());assertThrows(BusinessException.class,()->validator().pair(OP,"SH600030",RAW,PREV,DAY,List.of(bar(PREV,"100",1),bar(DAY,"50",1)),days(),illegal));}
}
